-- Refresh the builtin Story Arc catalog's creative promises for NEW selections.
-- Protect custom text by updating only rows still matching their canonical prior value.
-- Do not touch public.story_arcs or public.story_arc_beats: existing project choices stay intact.
-- UUIDs, beat roles, beat labels and beat order are unchanged.

WITH rewrites (template_id, original_description, revised_description) AS (
  VALUES
    ('a0000001-0000-0000-0000-000000000027'::uuid, 'A multigenerational family arc built around founding choices, inheritance, buried conflict, generational repetition, fracture, revelation, reckoning, and legacy.', 'An unruly generational epic of consuming love, inherited shame, fierce ambition, rivalries, secrets, and choices that echo catastrophically through time. Legacy may be triumph, curse, or a startling mixture.'),
    ('a0000001-0000-0000-0000-000000000026'::uuid, 'A moral transformation arc in which a damaged or compromised protagonist receives a chance to change, relapses, faces the truth, sacrifices, and acts differently when it matters.', 'A dangerous, hard-fought rebirth where a compromised person faces temptation, catastrophic relapse, and the ultimate cost of acting against their old self. Redemption must be proven through stunning action, not declarations.'),
    ('a0000001-0000-0000-0000-000000000025'::uuid, 'A plan-execution arc built around a desirable target, specialized crew, preparation, layered complications, betrayal, improvisation, and escape or capture.', 'An audacious caper of impossible ambition, eccentric specialists, clashing loyalties, outrageous complications, clever improvisation, and double-crosses that change the job itself. The story must thrill, not read like a logistics plan.'),
    ('a0000001-0000-0000-0000-000000000024'::uuid, 'A vengeance arc built around injury, vow, preparation, escalating retaliation, moral cost, counterattack, reckoning, and the consequences of revenge.', 'A savage vengeance tale of obsession, inventive retaliation, treacherous alliances, escalating counterstrikes, and a victory that may taste monstrous. Revenge must change its pursuer and the world they injure.'),
    ('a0000001-0000-0000-0000-000000000023'::uuid, 'An identity-development arc built around disruption, experimentation, belonging, consequences, disillusionment, self-recognition, and an adult choice.', 'An unruly journey of intoxicating discovery, humiliation, dangerous belonging, fierce attachments, and irreversible self-definition. Growing up may be ecstatic, ugly, strange, or morally compromised rather than wholesome.'),
    ('a0000001-0000-0000-0000-000000000022'::uuid, 'A historical survival arc in which ordinary life is ruptured by conflict, adaptation becomes necessary, losses accumulate, and survival requires an impossible choice.', 'A raw historical survival saga of desperation, fragile loyalty, savage irony, heartbreaking courage, and irreversible choices. Let lived history collide with unpredictable human decisions rather than procedural campaign summaries.'),
    ('a0000001-0000-0000-0000-000000000021'::uuid, 'A growth-driven fantasy arc organized around discovering a system, incremental advancement, escalating tests, defeat, breakthrough, and a tier-defining climax.', 'An electrifying climb through imaginative power systems, spectacular trials, fierce rivals, and costly breakthroughs. Each tier unlocks different dangers and freedoms, not merely bigger numbers.'),
    ('a0000001-0000-0000-0000-000000000020'::uuid, 'A discovery-and-pursuit thriller built around clues, expanding conspiracy, hidden history, betrayal, decoding, and a race to prevent a larger outcome.', 'A thrilling rabbit hole of dangerous discoveries, hidden power, treacherous allies, astonishing connections, and revelations that redraw reality. Clues must unleash human danger and consequential action, not paperwork.'),
    ('a0000001-0000-0000-0000-000000000019'::uuid, 'A paired romance-and-danger arc in which trust grows under threat and the relationship becomes essential to surviving the final confrontation.', 'A combustible romance under mounting peril, where chemistry, secrets, betrayal, and risky trust reshape the danger itself. Deliver a thrilling, earned joint climax that makes the relationship essential to survival.'),
    ('a0000001-0000-0000-0000-000000000018'::uuid, 'A romance structure that interlocks a competitive season or athletic goal with attraction, forced proximity, public pressure, setbacks, and an emotional payoff.', 'An exhilarating collision of competitive ambition, fierce rivalry, obsessive drive, public pressure, and romantic chemistry. Make both the athletic climax and love choice thrilling and costly, with an earned romantic future.'),
    ('a0000001-0000-0000-0000-000000000017'::uuid, 'A horror arc that moves from subtle wrongness through intrusion, confirmation, isolation, rule discovery, full manifestation, and a survival-or-doom climax.', 'A nightmare engine of encroaching wrongness, bizarre revelations, collapsing safety, and a genuinely terrifying manifestation. Leave unforgettable images and consequences that disturb the reader long after the ending.'),
    ('a0000001-0000-0000-0000-000000000016'::uuid, 'A compact seven-point plotting framework: hook, first turn, first pinch, midpoint, second pinch, second turn, and climactic resolution.', 'A sharp seven-turn architecture of irresistible contrast, disruptive choices, severe pressure, and a startling consequential payoff. Let the selected genre—not a generic plotting formula—determine the spectacle or intimacy.'),
    ('a0000001-0000-0000-0000-000000000015'::uuid, 'A large-scale quest arc built around a threatened world, fellowship, widening trials, revelation, catastrophic setback, sacrifice, and a final objective.', 'A vast, perilous adventure of strange civilizations, impossible bargains, magical terrors, fractured fellowship, and sacrifices capable of remaking the world. Each revelation should change the quest itself.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'A high-intensity romance arc centered on dangerous attraction, power imbalance, boundaries, vulnerability, rupture, reckoning, and an earned chosen relationship.', 'A transgressive romance of consuming desire, obsession, dangerous dependence, temptation, moral compromise, betrayal, and shifting power. Let passion cause shocking and intimate consequences. Development need not mean rehabilitation, and an earned romantic future need not be wholesome, domestic, or emotionally tidy.'),
    ('a0000001-0000-0000-0000-000000000013'::uuid, 'An oppression-to-resistance arc in which the protagonist awakens to systemic control, commits to defiance, pays for resistance, and confronts the regime.', 'A fierce rebellion of seductive power, dangerous loyalty, treachery, desperate sacrifice, and upheaval. Resistance may liberate or corrupt; the new order need not be reassuring.'),
    ('a0000001-0000-0000-0000-000000000012'::uuid, 'A science-fiction problem-solving arc built around an impossible condition, iterative failure, discovery, sacrifice, and a hard-earned solution.', 'A mind-bending survival story of impossible phenomena, terrifying implications, emotional collisions, and discoveries that redraw what is possible. The breakthrough must change people and their world, not merely fix a device.'),
    ('a0000001-0000-0000-0000-000000000011'::uuid, 'A pressure-driven thriller structure organized around a credible threat, shrinking time, narrowing options, reversals, and a deadline climax.', 'A relentless countdown of ingenious setbacks, desperation, betrayals, and surprising changes in what the threat demands. End in a nail-biting, earned collision at the clock''s edge.'),
    ('a0000001-0000-0000-0000-000000000010'::uuid, 'A dual-engine fantasy arc in which external fantasy stakes and central romance escalate together and become inseparable at the climax.', 'A high-intensity collision of dangerous magic, wonder, forbidden or consuming desire, and loyalties that can remake a world. Fantasy conflict and romantic choices must transform one another spectacularly.'),
    ('a0000001-0000-0000-0000-000000000009'::uuid, 'A suspense arc in which ordinary life destabilizes through suspicion, manipulation, layered revelations, betrayal, and a final confrontation with the deeper truth.', 'A feverish thriller of obsession, intimate treachery, shifting guilt, and revelations that turn familiar people terrifying. Make the final truth shocking, earned, and emotionally destabilizing.'),
    ('a0000001-0000-0000-0000-000000000008'::uuid, 'A relationship-first arc built around attraction, resistance, vulnerability, rupture, and an earned happily-ever-after or happy-for-now ending.', 'A passionate romance driven by combustible chemistry, clashing desires, revelatory intimacy, costly rupture, and a grand act of choosing love. Deliver the promised HEA/HFN with an exciting, personal route to it—not interchangeable relationship talks.'),
    ('a0000001-0000-0000-0000-000000000007'::uuid, 'A four-part structure that develops an idea, introduces a turn, and creates meaning through juxtaposition rather than a central conflict.', 'An inventive four-part architecture that builds fascination, then creates a radical change in meaning through juxtaposition rather than mandatory conflict. The turn can be funny, uncanny, devastating, exquisite, or sublime.'),
    ('a0000001-0000-0000-0000-000000000006'::uuid, 'A five-part dramatic arc built around rising action, a climax, and falling consequences.', 'Five movements of rising pressure toward a breathtaking dramatic collision, followed by consequences that fracture or remake lives. The author''s genre decides whether the climax is horrifying, ecstatic, intimate, or devastating.'),
    ('a0000001-0000-0000-0000-000000000005'::uuid, 'Dan Harmon''s eight-step cycle: a character leaves comfort, adapts through conflict, and returns changed.', 'An eight-movement spiral from familiar desire into startling discovery, costly possession, and a return that cannot restore the old world. Transformation need not equal improvement.'),
    ('a0000001-0000-0000-0000-000000000004'::uuid, 'A practical fifteen-beat structure for commercial, character-driven stories with a clear emotional arc.', 'A propulsive fifteen-beat story of bold choices, unpredictable encounters, major reversals, and the vivid pleasures or terrors of the authored premise. Its transformation may be exhilarating, grotesque, tragic, tender, or morally dark.'),
    ('a0000001-0000-0000-0000-000000000003'::uuid, 'Crime-driven structure: hook, investigation, false leads, reveal. Engineered for detective stories, thrillers, and puzzles.', 'An irresistible mystery of volatile people, seductive false answers, and revelations that keep changing whom readers trust. Deliver a surprising but fair truth with a personal cost far beyond closing the case.'),
    ('a0000001-0000-0000-0000-000000000002'::uuid, 'Joseph Campbell''s monomyth: separation, initiation, return. Best for hero-driven adventure and coming-of-age stories.', 'An extraordinary journey through strange encounters, dangerous bonds, temptation, ordeal, and a changed return. The hero may emerge triumphant, haunted, compromised, or monstrous when the authored story warrants it.'),
    ('a0000001-0000-0000-0000-000000000001'::uuid, 'Classical three-act structure: setup, confrontation, resolution. Universal across most fiction genres.', 'A versatile three-act engine for vivid, escalating drama: an irresistible rupture, a middle that changes what the struggle means, and a decisive, unforgettable consequence. Let the author''s genre choose the intensity and aftertaste, not a tidy default.')
)
UPDATE public.story_arc_templates AS t
SET description = r.revised_description
FROM rewrites AS r
WHERE t.id = r.template_id AND t.description = r.original_description;

WITH beat_rewrites (template_id, role, original_text, revised_text) AS (
  VALUES
    ('a0000001-0000-0000-0000-000000000027'::uuid, 'legacy', 'Resolve the saga by showing what is ultimately passed forward.', 'Show an unforgettable inheritance or rupture that transforms how the reader understands every generation''s choices.'),
    ('a0000001-0000-0000-0000-000000000026'::uuid, 'redemptive_act', 'Prove the transformation through decisive action under maximum pressure.', 'Demand an extraordinary, costly deed that proves genuine change under maximum temptation; confession alone is insufficient.'),
    ('a0000001-0000-0000-0000-000000000025'::uuid, 'escape_or_capture', 'Resolve possession of the target and the team''s immediate survival or capture.', 'Pay off the heist through a daring, earned final gambit that transforms who gets the prize and whom the crew can trust.'),
    ('a0000001-0000-0000-0000-000000000024'::uuid, 'reckoning', 'Bring avenger and target into the decisive confrontation.', 'Force a fierce, unforgettable final confrontation; mercy, ruin, violence, or reversal must carry irrevocable costs.'),
    ('a0000001-0000-0000-0000-000000000023'::uuid, 'integrated_identity', 'Resolve the arc with a more mature, self-authored identity.', 'Reveal the emerging self through a startling, costly choice, whether admirable, damaged, or unsettling.'),
    ('a0000001-0000-0000-0000-000000000022'::uuid, 'decisive_event', 'Bring the protagonist through the defining confrontation, escape, battle, or survival test.', 'Deliver a historically grounded, extraordinary decisive event whose survival, betrayal, or loss changes everything.'),
    ('a0000001-0000-0000-0000-000000000021'::uuid, 'tier_climax', 'Win or survive the defining challenge of this progression stage.', 'Pay off hard-won powers and relationships in a spectacular, inventive trial with lasting consequences beyond a level increase.'),
    ('a0000001-0000-0000-0000-000000000020'::uuid, 'confrontation_and_truth', 'Defeat or expose the central threat while making the hidden truth unavoidable.', 'Turn the astonishing but earned truth into irreversible upheaval through a high-stakes confrontation, not revelation alone.'),
    ('a0000001-0000-0000-0000-000000000019'::uuid, 'joint_showdown', 'Resolve the central danger through coordinated action and emotional commitment.', 'Resolve the danger through surprising coordinated action driven by an emotionally costly romantic decision, not just exposure or outside rescue.'),
    ('a0000001-0000-0000-0000-000000000018'::uuid, 'game_day_choice', 'Resolve the defining athletic challenge alongside the central emotional choice.', 'Make the defining athletic moment and romantic decision collide in one emotionally charged, unforgettable payoff.'),
    ('a0000001-0000-0000-0000-000000000017'::uuid, 'full_manifestation', 'Bring the horror into its most complete and unavoidable form.', 'Bring the horror into an unmistakably nightmarish form that destroys safety or meaning, not a generic threatening encounter.'),
    ('a0000001-0000-0000-0000-000000000017'::uuid, 'final_image', 'Resolve survival or doom while leaving the intended emotional residue of the horror.', 'Leave a haunting, specifically horrific aftershock whether anyone survives, escapes, or becomes part of the horror.'),
    ('a0000001-0000-0000-0000-000000000016'::uuid, 'resolution', 'Deliver the decisive act or encounter and establish the central story''s consequential outcome.', 'Pay off the core contrast through a decisive, genre-faithful transformation, never a routine wrap-up.'),
    ('a0000001-0000-0000-0000-000000000015'::uuid, 'final_objective', 'Confront the primary antagonist or complete the decisive objective.', 'Deliver a breathtaking and causally earned event that transforms the world''s future at a profound personal price.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'boundary_drawn', 'Establish the limits, fears, and power conditions that define the relationship''s danger.', 'Expose a dangerous imbalance or forbidden limit that intensifies the attraction and provokes consequential choices; this is not a recurring discussion of relationship rules.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'entanglement', 'Make separation harder as desire, leverage, dependency, or shared stakes increase.', 'Make desire, secrecy, dependence, and compromising choices collide until a new situation becomes inescapable.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'reckoning', 'Force accountability, self-recognition, and confrontation with the relationship''s central harm or fear.', 'Force an emotionally explosive encounter with the relationship''s real price; it may intensify devotion, ruin it, corrupt it, or change it, not automatically redeem anyone.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'chosen_terms', 'Make a decisive choice that establishes what the relationship can and cannot become.', 'Deliver a bold, costly, defining choice about the bond through decisive action rather than a list of healthy boundaries.'),
    ('a0000001-0000-0000-0000-000000000014'::uuid, 'earned_resolution', 'Resolve the central romantic conflict with agency, consequences, and a stable chosen future.', 'Resolve the central romance through a memorable, earned choice with lasting consequences; the future may remain obsessive, precarious, dangerous, or morally unsettling.'),
    ('a0000001-0000-0000-0000-000000000013'::uuid, 'confrontation', 'Bring the rebellion and regime into decisive conflict.', 'Make the defining clash an irreversible rupture that exposes what gaining power really costs, not just a formal change of control.'),
    ('a0000001-0000-0000-0000-000000000012'::uuid, 'deeper_discovery', 'Reveal the hidden rule, mechanism, or truth that changes the problem definition.', 'Reveal a staggering new truth or rule that transforms the problem and demands a deeply personal response.'),
    ('a0000001-0000-0000-0000-000000000011'::uuid, 'showdown', 'Resolve the central threat at or immediately before the deadline.', 'At the deadline, force an inventive, decisive sacrifice or gamble that produces the promised suspense payoff.'),
    ('a0000001-0000-0000-0000-000000000010'::uuid, 'final_battle_and_choice', 'Bring the defining fantasy stakes and romantic choice together in one consequential climax; a literal battle is not required.', 'Deliver an astonishing fantasy consequence decided by a defining, costly romantic choice; no literal battle is required.'),
    ('a0000001-0000-0000-0000-000000000009'::uuid, 'final_confrontation', 'Force the protagonist to confront the true source of danger and act on the full truth.', 'Force a genuinely unnerving clash with the true source of danger and a revelation that changes the protagonist''s world.'),
    ('a0000001-0000-0000-0000-000000000008'::uuid, 'grand_choice', 'Make a costly, active choice that proves what the relationship now means.', 'Demand a daring, costly, unmistakably romantic action that transforms both lives and earns the promised future.'),
    ('a0000001-0000-0000-0000-000000000007'::uuid, 'ten', 'Introduce a surprising new element or perspective that reframes what came before.', 'Introduce a daring new perspective or event that recasts everything established without manufacturing a villain.'),
    ('a0000001-0000-0000-0000-000000000006'::uuid, 'climax', 'The decisive turning point where the conflict reaches maximum intensity.', 'Deliver an irreversible confrontation or choice at maximum intensity, surprising in its event and inevitable in hindsight.'),
    ('a0000001-0000-0000-0000-000000000005'::uuid, 'change', 'The character shows how the experience has changed their choices, for better or worse.', 'Show the character transformed through a bold, specific choice or consequence, for better, worse, or stranger.'),
    ('a0000001-0000-0000-0000-000000000004'::uuid, 'fun_and_games', 'Deliver the central promise of the premise as complications grow.', 'Deliver imaginative, varied events that embody the unique promise of this premise rather than repeating one type of obstacle.'),
    ('a0000001-0000-0000-0000-000000000004'::uuid, 'finale', 'The protagonist acts on changed understanding or commitment, bringing the central conflict to a consequential turning point.', 'Deliver an exceptional, emotionally charged final action whose consequences cannot simply be tidied away.'),
    ('a0000001-0000-0000-0000-000000000003'::uuid, 'confrontation', 'The protagonist confronts the antagonist with the truth.', 'Reveal the earned truth in a dangerous, character-specific confrontation that irreversibly changes loyalties or lives.'),
    ('a0000001-0000-0000-0000-000000000002'::uuid, 'resurrection', 'A final climactic test where the hero is transformed.', 'Force a defining, extreme final test that proves what the journey has made the hero, for good or ill.'),
    ('a0000001-0000-0000-0000-000000000001'::uuid, 'midpoint', 'A reversal or revelation that doubles the stakes and reframes the conflict.', 'Deliver a surprising, character-caused reversal that changes the conflict itself, not merely its difficulty.'),
    ('a0000001-0000-0000-0000-000000000001'::uuid, 'climax', 'The decisive confrontation where the protagonist''s arc turns.', 'Force an extraordinary, irreversible, genre-faithful act that transforms the characters'' world.')
)
UPDATE public.story_arc_templates AS t
SET beats = (
  SELECT jsonb_agg(
    CASE WHEN r.role IS NOT NULL
      THEN jsonb_set(b.beat, '{description}', to_jsonb(r.revised_text), false)
      ELSE b.beat END ORDER BY b.position
  )
  FROM jsonb_array_elements(t.beats) WITH ORDINALITY AS b(beat, position)
  LEFT JOIN beat_rewrites AS r ON r.template_id = t.id
    AND r.role = b.beat->>'role' AND r.original_text = b.beat->>'description'
)
WHERE jsonb_typeof(t.beats) = 'array'
  AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(t.beats) AS beat
    JOIN beat_rewrites AS r ON r.template_id = t.id
      AND r.role = beat->>'role' AND r.original_text = beat->>'description'
  );
